// Original PNG artwork embedded so state edits and reloads need no image requests.
const ORIGINAL_GAME_ICONS={"academy":"data:image/png;base64,","artificial_intelligence":"data:image/png;base64,","credits":"data:image/png;base64,","economy":"data:image/png;base64,","gaia_project":"data:image/png;base64,","gaiaformer":"data:image/png;base64,","knowledge":"data:image/png;base64,","mine":"data:image/png;base64,","navigation":"data:image/png;base64,","ore":"data:image/png;base64,","planetary_institute":"data:image/png;base64,","power":"data:image/png;base64,","qic":"data:image/png;base64,","research_lab":"data:image/png;base64,","science":"data:image/png;base64,","terraforming":"data:image/png;base64,","trading_station":"data:image/png;base64,","vp":"data:image/png;base64,"};
function gameIconSource(file){return ORIGINAL_GAME_ICONS[file]??'';}
// Original game artwork extracted from the rulebook, not AI-generated symbols.
function gameMetricIcon(key){
 const label={power:'파워',powerTokens:'파워 토큰',bowl2Tokens:'Ⅱ그릇 토큰',bowl3PowerToken:'Ⅲ그릇 토큰',gaiaformer:'가이아포머',brainstone:'두뇌석'}[key]??iconInfo(key)[1];
 const aliases={bowl1:'power',bowl2:'power',bowl3:'power',bowl2Tokens:'power',bowl3PowerToken:'power',powerTokens:'power',gaia:'gaia_project'};
 const file=aliases[key]??key;
 const supported=['credits','ore','knowledge','qic','power','vp','terraforming','navigation','artificial_intelligence','gaia_project','economy','science','mine','trading_station','research_lab','academy','planetary_institute','gaiaformer'];
 if(!supported.includes(file))return `<span class="metricIcon metricIconFallback" role="img" aria-label="${esc(label)}"></span>`;
 const badge={bowl1:'Ⅰ',bowl2:'Ⅱ',bowl3:'Ⅲ',bowl2Tokens:'Ⅱ',bowl3PowerToken:'Ⅲ'}[key];
 const img=`<img class="metricIcon originalGameIcon" src="${gameIconSource(file)}" alt="${esc(label)}" width="28" height="28" decoding="async">`;
 return badge?`<span class="powerIconBadge">${img}<span aria-hidden="true">${badge}</span></span>`:img;
}

function gameMetricChip(key,value){
 const [color,label]=iconInfo(key);
 return `<span class="metric gameMetric" style="--metric-color:${color}" title="${esc(label)} ${value}" aria-label="${esc(label)} ${value}">${gameMetricIcon(key)}<b class="metricValue">${value}</b><small class="metricLabel">${esc(key==='qic'?'정보큐브':label)}</small></span>`;
}
function gamePowerArea(p,key){
 const pow=p.power??{},n=pow[key]??0,label={gaia:'가이아 구역',bowl1:'Ⅰ그릇',bowl2:'Ⅱ그릇',bowl3:'Ⅲ그릇'}[key];
 const tokens=Array.from({length:Math.min(6,Math.max(0,n))},()=>`<img src="${gameIconSource('power')}" alt="" width="13" height="13">`).join('');
 return `<div class="powerArea area-${key}" aria-label="${label} 파워 토큰 ${n}개${pow.brainstone===key?' · 두뇌석 1개':''}"><span class="powerAreaLabel">${label}</span><strong>${n}<small>개</small></strong><span class="powerTokenRow" aria-hidden="true">${tokens}${n>6?'<span>…</span>':''}</span>${pow.brainstone===key?'<span class="brainstoneBadge">두뇌석 1</span>':''}</div>`;
}
function gameResearchChip(key,level){
 const [color,label]=iconInfo(key);
 return `<span class="metric gameMetric researchMetric" style="--metric-color:${color}" aria-label="${esc(label)} ${level}단계">${gameMetricIcon(key)}<b class="metricValue">${level}<small>단계</small></b><small class="metricLabel">${esc(label)}</small><span class="researchSteps" aria-hidden="true">${Array.from({length:5},(_,i)=>`<i class="${i<level?'reached':''}"></i>`).join('')}</span></span>`;
}
function gameStatusAmounts(p,{research=false,resources=true,power=true}={}){
 const r=p.resources??{};
 const tracks=['terraforming','navigation','artificial_intelligence','gaia_project','economy','science'];
 return (resources?`<div class="resourceStrip gameResourceStrip" role="group" aria-label="보유 자원">${['credits','ore','knowledge','qic','vp'].map(k=>gameMetricChip(k,r[k]??0)).join('')}</div>`:'')+(power?`<div class="powerBoardHeading">파워 토큰 <small>Ⅰ → Ⅱ → Ⅲ → Ⅰ</small></div><div class="powerBoard" role="group" aria-label="종족판 파워 구역">${['gaia','bowl2','bowl1','bowl3'].map(k=>gamePowerArea(p,k)).join('')}</div>`:'')+(research?`<div class="researchStrip gameResearchStrip" role="group" aria-label="연구 단계">${tracks.map(k=>gameResearchChip(k,p.researchLevels?.[k]??0)).join('')}</div>`:'');
}
